import{z as E,x as o,o as m,c as p,q as s,j as t,D as i,d as n,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"贝尔曼期望与最优方程","description":"","frontmatter":{"title":"贝尔曼期望与最优方程","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/bellman-equations-rl.md","filePath":"llm/bellman-equations-rl.md","lastUpdated":1791413859000}'),B={name:"llm/bellman-equations-rl.md"};function g(_,a,A,d,T,V){const e=o("Mermaid");return m(),p("div",null,[a[2]||(a[2]=s('<h1 id="贝尔曼期望与最优方程" tabindex="-1">贝尔曼期望与最优方程 <a class="header-anchor" href="#贝尔曼期望与最优方程" aria-label="Permalink to &quot;贝尔曼期望与最优方程&quot;">​</a></h1><div class="epigraph"><p>价值的定义里已经藏着它的算法：今天的价值，等于奖励加折扣后的明天价值；最优性只是把其中一步换成 max。</p><footer>—— 据 Bellman, Dynamic Programming, 1957；Sutton &amp; Barto, Reinforcement Learning: An Introduction, 2018, 第 4 章整理</footer></div><p><a href="/llm/return-discounting">上一课</a>把回报 \\(G_t\\) 与价值 \\(V^\\pi\\)、\\(Q^\\pi\\) 定义了出来，但按定义算价值要对指数多的轨迹求和，实际不可算。缺口是把定义变成递归：\\(G_t=r_t+\\gamma G_{t+1}\\) 这个恒等式取期望后，价值自己满足自己的方程。本课写贝尔曼期望方程（固定 \\(\\pi\\)）与贝尔曼最优方程（算子形式），并用压缩映射自足地证明解存在且唯一——同一套不动点语言在经济学栏的<a href="/econ/bellman-equation">贝尔曼方程</a>出现过，本课不预设那边的结论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课结束时价值函数只是三个字母。枚举轨迹不可行：状态数大、轨迹长指数级，\\(V^\\pi\\) 的定义式 \\(\\mathbb{E}[\\sum_k\\gamma^k r_{t+k}]\\) 里求和跑遍所有未来。需要一个对每个状态逐点成立的方程，让「无穷长的未来」缩成「一步奖励 + 一步递归」；还要回答递归不会循环定义吗——价值右边出现价值，凭什么它有解且只有一个。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对期望方程，把回报拆成首项与余项再取条件期望，得<strong>贝尔曼期望方程</strong>：对所有 \\(s\\)，</p> \\[V^\\pi(s)=\\sum_a \\pi(a\\mid s)\\Big[r(s,a)+\\gamma\\sum_{s&#39;}P(s&#39;\\mid s,a)V^\\pi(s&#39;)\\Big] \\]\\[Q^\\pi(s,a)=r(s,a)+\\gamma\\sum_{s&#39;}P(s&#39;\\mid s,a)V^\\pi(s&#39;) \\]<p>把逐点的 max 写进去，定义<strong>贝尔曼最优算子</strong> \\((T^*v)(s)=\\max_a\\big[r(s,a)+\\gamma\\,\\mathbb{E}_{s&#39;}v(s&#39;)\\big]\\)，最优价值就是它的不动点：</p> \\[V^*(s)=\\max_a\\Big[r(s,a)+\\gamma\\sum_{s&#39;}P(s&#39;\\mid s,a)V^*(s&#39;)\\Big] \\]<p>评估与控制各用一支：固定 \\(\\pi\\) 的期望方程给出「\\(\\pi\\) 有多好」，最优方程给出「最好能多好」；下一课的算法就是这两支方程的交替。</p><p><span class="marginnote">直觉类比：\\(V^\\pi(s)\\) 就是「从 \\(s\\) 出发、以后一直按 \\(\\pi\\) 的习惯走，平均能攒多少分」；\\(Q^\\pi(s,a)\\) 多问一句「第一步先强制走 \\(a\\)、之后再交给 \\(\\pi\\)，平均多少分」。多出来的那个 \\(a\\) 正是控制算法的撬杆——改良 \\(\\pi\\) 时就挑 \\(Q\\) 最大的动作。</span></p>',12)),(m(),t(l,null,{default:i(()=>[r(e,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20V0%5B%22%E4%BB%BB%E6%84%8F%E5%88%9D%E5%80%BC%20v_0%22%5D%20--%3E%20TPI%5B%22T_pi%EF%BC%9A%E6%8C%89%20pi%20%E6%B1%82%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20V0%20--%3E%20TST%5B%22T*%EF%BC%9A%E5%AF%B9%20a%20%E5%8F%96%20max%22%5D%0A%20%20TPI%20--%3E%20VPI%5B%22%E4%B8%8D%E5%8A%A8%E7%82%B9%20V%5Epi%EF%BC%88%E8%AF%84%E4%BC%B0%EF%BC%89%22%5D%0A%20%20TST%20--%3E%20VST%5B%22%E4%B8%8D%E5%8A%A8%E7%82%B9%20V*%EF%BC%88%E6%9C%80%E4%BC%98%EF%BC%89%22%5D%0A%20%20VPI%20--%3E%20IMP%5B%22%E5%AF%B9%20V%5Epi%20%E8%B4%AA%E5%BF%83%E5%8D%B3%E6%94%B9%E8%BF%9B%22%5D%0A%20%20IMP%20--%3E%20VST%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>递归不是循环定义，因为右边是算子。对任意两个价值表 \\(v,w\\)，先估一步：</p> \\[\\big|(T^*v)(s)-(T^*w)(s)\\big|\\le\\gamma\\max_{s&#39;}|v(s&#39;)-w(s&#39;)| \\]<p>max 只会把两表的差拉平或缩小（对 \\(a\\) 取 max 满足次可加），折扣再统一乘 \\(\\gamma\\)。于是 \\(\\|T^*v-T^*w\\|_\\infty\\le\\gamma\\|v-w\\|_\\infty\\)：\\(T^*\\) 是压缩映射。固定 \\(\\pi\\) 的期望算子 \\(T_\\pi\\) 同理，只是把 max 换成按 \\(\\pi\\) 加权，压缩常数不变。Banach 不动点定理随即给出三件事：<strong>不动点存在且唯一</strong>（\\(V^*\\)、\\(V^\\pi\\) 良定义）；<strong>从任意初值迭代 \\(v_{k+1}=T^*v_k\\) 必收敛</strong>；<strong>误差每轮至少乘 \\(\\gamma\\)</strong>，压到精度 \\(\\varepsilon\\) 需约 \\(\\log(1/\\varepsilon)/\\log(1/\\gamma)\\) 轮。</p><p><span class="marginnote">收敛速度由 \\(\\gamma\\) 直接定价：\\(\\gamma=0.9\\) 时每轮误差至少缩十倍，\\(\\gamma=0.999\\) 则一轮只缩千分之一——耐心策略的代价在算法侧原样重现。</span></p><p>最优方程还内含<strong>最优性原理</strong>：不论如何到达 \\(s\\)，余下的最优只看 \\(s\\)——这正是马尔可夫性（第一课）在方程里的样子，也是「值迭代从任意初始化出发也合法」的原因。</p>',6)),(m(),t(l,null,{default:i(()=>[r(e,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20LR%0A%20%20V0%5B%22%E4%BB%BB%E6%84%8F%E5%88%9D%E5%80%BC%20v0%EF%BC%8C%E8%AF%AF%E5%B7%AE%20%CE%94%22%5D%20--%3E%20R1%5B%22%E8%BF%87%E4%B8%80%E9%81%8D%E7%AE%97%E5%AD%90%20T*%22%5D%0A%20%20R1%20--%3E%20E1%5B%22%E8%AF%AF%E5%B7%AE%E8%87%B3%E5%A4%9A%20%CE%B3%CE%94%22%5D%0A%20%20E1%20--%3E%20R2%5B%22%E5%86%8D%E8%BF%87%E4%B8%80%E9%81%8D%20T*%22%5D%0A%20%20R2%20--%3E%20E2%5B%22%E8%AF%AF%E5%B7%AE%E8%87%B3%E5%A4%9A%20%CE%B3%C2%B2%CE%94%22%5D%0A%20%20E2%20--%3E%20R3%5B%22%E6%8C%81%E7%BB%AD%E8%BF%AD%E4%BB%A3%E2%80%A6%E2%80%A6%22%5D%0A%20%20R3%20--%3E%20CV%5B%22%E8%AF%AF%E5%B7%AE%E4%BD%8E%E4%BA%8E%20%CE%B5%20%E6%97%B6%E5%81%9C%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p>这张图回答：为什么初值猜错了也不要紧、迭代到第几轮可以停。每一遍算子都把误差表整体乘一次 \\(\\gamma\\)，所以轮数只由「初值差多远」和「要多准」的对数决定，与状态多少无关。</p><p><span class="marginnote">数字实例：取 \\(\\gamma=0.9\\)，初值乐观得离谱、每格误差 100 分，那么 1 轮后至多差 90 分，2 轮后 81 分……要压到 1 分以内约需 \\(\\log 100/\\log(1/0.9)\\approx 44\\) 轮；换成 \\(\\gamma=0.99\\)，同样精度要 400 多轮。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>以上论证要求 \\(\\gamma\\lt 1\\)（或回合必终止）：无折扣的无限期问题可能没有有限值。逐状态的方程在<strong>表格</strong>上精确成立；换成函数逼近，「每个状态满足方程」退化为「整体误差可压小」，自举的偏差正是从这里进来的——那是本课程后面的致命三要素课的主题。期望方程与最优方程也不能混用：拿 \\(T^*\\) 迭代去评估一个次优 \\(\\pi\\)，收敛到的是 \\(V^*\\) 而不是 \\(V^\\pi\\)，评估就错了。</p><p><span class="marginnote">常见误区：想算「某个手写策略值多少分」，却把带 max 的最优方程拿来迭代，最后得到的永远是满分答案 \\(V^*\\)，而不是那个策略的真实价值 \\(V^\\pi\\)。max 一旦写进方程，问的就不再是「它怎么样」，而是「最好能怎么样」。</span></p><p>后课默认：\\(V^\\pi\\) 是 \\(T_\\pi\\) 的不动点，\\(V^*\\) 是 \\(T^*\\) 的不动点，两者都 \\(\\gamma\\)-压缩。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>贝尔曼期望方程：\\(V^\\pi(s)=\\mathbb{E}_\\pi[r+\\gamma V^\\pi(s&#39;)]\\)，评估固定策略。</li><li>贝尔曼最优方程：\\(V^*=T^*V^*\\)，右端多一个 \\(\\max_a\\)，刻画最优。</li><li>压缩映射给唯一解：\\(\\gamma\\lt 1\\) 下迭代收敛，每轮误差乘 \\(\\gamma\\)。</li><li>收敛轮数约 \\(\\log(1/\\varepsilon)/\\log(1/\\gamma)\\)；\\(\\gamma\\) 近 1 时方程成立但迭代很慢。</li><li>表格上逐点精确；函数逼近把精确方程换成可压误差，为后面的发散问题埋线。</li><li>出处：Bellman, <em>Dynamic Programming</em>, 1957；Sutton &amp; Barto, <em>Reinforcement Learning</em>, 2018 第 4 章。</li></ul>',8))])}const c=E(B,[["render",g]]);export{h as __pageData,c as default};
